The crash is a stack-buffer-overflow READ 8. Let me look at the `SC_ASN1_BIT_FIELD` case in `asn1_decode_entry` more carefully. The `decode_bit_field` function reads `data[i/8]` where `data` is `u8 data[sizeof(unsigned int)]` = 4 bytes on 32-bit or 8 bytes on 64-bit. The loop `for (i = 0; i < n; i += 8)` reads `data[i/8]`. If `n` is larger than `sizeof(data)*8`, this would read out of bounds.

But wait, `decode_bit_string` checks `if (outlen < octets_left) return SC_ERROR_BUFFER_TOO_SMALL;` where `outlen = sizeof(data) = 8` (on 64-bit). So `octets_left` can be at most 8, meaning `n` can be at most `8*8 - zero_bits = 64`. The loop `for (i = 0; i < n; i += 8)` reads `data[i/8]` for `i = 0, 8, 16, ..., 56`, so `data[0]` through `data[7]` - that's fine for 8-byte data.

Hmm, but the crash is READ 8. Let me look at the `SC_ASN1_BIT_STRING` case in `asn1_decode_entry`:

```c
case SC_ASN1_BIT_STRING_NI:
case SC_ASN1_BIT_STRING:
        if (parm != NULL) {
                int invert = entry->type == SC_ASN1_BIT_STRING ? 1 : 0;
                assert(len != NULL);
                if (objlen < 1) {
                        r = SC_ERROR_INVALID_ASN1_OBJECT;
                        break;
                }
                if (entry->flags & SC_ASN1_ALLOC) {
                        u8 **buf = (u8 **) parm;
                        if (objlen > 1) {
                                *buf = malloc(objlen-1);
                                if (*buf == NULL) {
                                        r = SC_ERROR_OUT_OF_MEMORY;
                                        break;
                                }
                        }
                        *len = objlen-1;
                        parm = *buf;
                }
                r = decode_bit_string(obj, objlen, (u8 *) parm, *len, invert, 0);
```

The crash is a stack-buffer-overflow READ 8. Let me look at the `SC_ASN1_OCTET_STRING` case:

```c
case SC_ASN1_OCTET_STRING:
        if (parm != NULL) {
                size_t c;
                assert(len != NULL);

                /* Strip off padding zero */
                if ((entry->flags & SC_ASN1_UNSIGNED)
                                && objlen > 1 && obj[0] == 0x00) {
                        objlen--;
                        obj++;
                }

                /* Allocate buffer if needed */
                if (entry->flags & SC_ASN1_ALLOC) {
                        u8 **buf = (u8 **) parm;
                        if (objlen > 0) {
                                *buf = malloc(objlen);
                                if (*buf == NULL) {
                                        r = SC_ERROR_OUT_OF_MEMORY;
                                        break;
                                }
                        }
                        c = *len = objlen;
                        parm = *buf;
                } else
                        c = objlen > *len ? *len : objlen;

                memcpy(parm, obj, c);
                *len = c;
        }
        break;
```

This looks fine. Let me look at the `SC_ASN1_OBJECT` case and other cases in `asn1_decode_entry`:

